selector_to_html = {"a[href=\"#pyskyfire.ducts.port.DomeSite\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.DomeSite\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DomeSite</span></span></dt><dd><p>The half-ellipse a stub leaves through, in machine coordinates.</p><p>The ellipse is the one the passage\u2019s own section is built on, centred where\nits two axes cross, which is the point a stub is aimed from. Only part of it\nis passage boundary: past <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">arc_limit</span></code> the section\u2019s fillets have taken\nover and the ellipse runs outboard of the metal, so a stub aimed out there\nwould leave through the side rather than the dome.</p></dd>", "a[href=\"#pyskyfire.ducts.port.DomeSite.exit_distance\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.DomeSite.exit_distance\">\n<span class=\"sig-name descname\"><span class=\"pre\">exit_distance</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>How far the dome sits from the ellipse centre along a stub [m].</p></dd>", "a[href=\"#pyskyfire.ducts.port.DomeSite.generator_exit\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.DomeSite.generator_exit\">\n<span class=\"sig-name descname\"><span class=\"pre\">generator_exit</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">offsets</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Where lines parallel to a stub leave the dome [m].</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">offsets</span></code> are distances across the stub within the section plane, as\nthe walls of a round tube sit at. What comes back is each line\u2019s\ncrossing measured along the stub from where its own centreline crosses,\nwhich is how far the tube\u2019s wall has to run back to meet the passage.</p></dd>", "a[href=\"#pyskyfire-ducts-port-domesite\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.port.DomeSite<a class=\"headerlink\" href=\"#pyskyfire-ducts-port-domesite\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.ducts.port.DomeSite.direction\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.DomeSite.direction\">\n<span class=\"sig-name descname\"><span class=\"pre\">direction</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Unit direction of a stub <code class=\"docutils literal notranslate\"><span class=\"pre\">angle</span></code> off the normal [shape (3,)].</p></dd>", "a[href=\"#pyskyfire.ducts.port.DomeSite.deepest_generator\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.DomeSite.deepest_generator\">\n<span class=\"sig-name descname\"><span class=\"pre\">deepest_generator</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">radius</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The furthest along a stub of <code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span></code> its own dome reaches [m].</p><p>Measured from where the centreline leaves the dome. Normally negative,\nbecause a curved dome falls away from the centreline\u2019s crossing to\neither side; positive for a stub tilted far enough that the dome\u2019s crest\nin the stub\u2019s own direction sits under the flange rather than on its\naxis.</p></dd>", "a[href=\"#pyskyfire.ducts.port.DomeSite.across\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.DomeSite.across\">\n<span class=\"sig-name descname\"><span class=\"pre\">across</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Unit direction across such a stub, within the section plane.</p></dd>", "a[href=\"#pyskyfire.ducts.port.DomeSite.clearance\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.DomeSite.clearance\">\n<span class=\"sig-name descname\"><span class=\"pre\">clearance</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Half the room the dome leaves across a stub aimed <code class=\"docutils literal notranslate\"><span class=\"pre\">angle</span></code> off the normal [m].</p><p>The tangents to the ellipse parallel to the stub bound it where they\ntouch the dome itself. Where a tangent touches out past\n<code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">arc_limit</span></code> it bounds nothing, because the metal there is fillet\nrather than dome, and the arc\u2019s own end takes over as the bound. So this\nis how far the dome arc reaches across the stub, on whichever side\nreaches less.</p></dd>", "a[href=\"#pyskyfire.ducts.port.DomeSite.__post_init__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.DomeSite.__post_init__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__post_init__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.port.DomeSite.angle_limit\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.DomeSite.angle_limit\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">angle_limit</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Furthest off the normal a stub may be aimed and still clear the fillet [rad].</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
